fun min(a: Long, b: Long): Long {
    return if (a < b) a else b
}

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val x = scanner.nextLong()
    val y = scanner.nextLong()
    val dp = LongArray(2 * n + 1)
    dp[1] = x
    for (i in 2..n) {
        dp[i] = min(dp[i - 1] + x, dp[(i + 1) / 2] + y + (i % 2).toLong() * x)
        dp[i - 1] = min(dp[i - 1], dp[i] + x)
    }

    println(dp[n])
}

